    replace("$('coverage').innerHTML=", "$('coverage-head').innerHTML='<tr><th>\u65b9\u6cd5\u5bb6\u65cf</th>'+DATA.papers.map(p=>'<th>'+esc(p.alias)+'</th>').join('')+'<th>\u8986\u76d6\u8bba\u6587\u6570</th></tr>';$('coverage').innerHTML=")
    replace('\u9875\u9762\u5df2\u5185\u5d4c\u5168\u90e8\u5c55\u793a\u6570\u636e，\u53ef\u4ee5\u79bb\u7ebf\u6253\u5f00。', '\u9875\u9762\u5df2\u5185\u5d4c\u5168\u90e8\u5c55\u793a\u6570\u636e，\u53ef\u4ee5\u79bb\u7ebf\u6253\u5f00。\u8de8\u8bba\u6587\u805a\u5408\u65b9\u6cd5\u5206\u7c7b\u5173\u7cfb，\u5404\u8bba\u6587\u7684\u8ba1\u7b97\u4f9d\u8d56\u5206\u522b\u4fdd\u7559。')
