        seed = selection['seed_count']
        s = s.replace('10 \u7bc7\u8bba\u6587 DAG', str(n) + ' \u7bc7\u8bba\u6587 DAG').replace('\u5341\u7bc7 DAG', str(n) + '\u7bc7 DAG').replace('\u5341\u7bc7\u4e4b\u540e', str(n) + '\u7bc7\u4e4b\u540e').replace('\u5341\u7bc7\u589e\u91cf\u8bd5\u9a8c\u7248', str(n) + '\u7bc7\u589e\u91cf\u8bd5\u9a8c\u7248')
        s = s.replace('\u539f\u4e09\u7bc7\u76ee\u5f55\u4fdd\u6301\u4e0d\u53d8；\u6309\u9884\u5148\u7559\u6863\u7684\u987a\u5e8f\u52a0\u5165\u4e03\u7bc7。', f'\u524d{seed}\u7bc7\u7684\u76ee\u5f55、\u5b9e\u4f8b\u4e0e\u7f16\u53f7\u4fdd\u6301\u4e0d\u53d8；\u6309\u7559\u6863\u987a\u5e8f\u7ee7\u7eed\u52a0\u5165{n - seed}\u7bc7。')
