COVERAGE_PANEL = '<div class="panel"><h2>\u65b9\u6cd5\u8986\u76d6\u7387：\u5df2\u6709\u76ee\u5f55\u80fd\u8986\u76d6\u65b0\u8bba\u6587\u591a\u5c11？</h2><p>\u8986\u76d6\u7387\u6309 DeepSeek \u5f52\u7c7b\u540e\u7684 Method \u7f16\u53f7\u8ba1\u7b97。\u540c\u4e00\u7bc7\u5185，\u540c\u4e00\u65b9\u6cd5\u7528\u591a\u6b21\u53ea\u8ba1\u4e00\u79cd；\u534f\u53d8\u91cf\u548c\u53c2\u6570\u5dee\u5f02\u5e94\u4fdd\u7559\u5728\u5b9e\u4f8b\u4e2d。M\u76ee\u5f55\u542b method（\u65b9\u6cd5）、strategy（\u7b56\u7565）、metric（\u6307\u6807），\u53e6\u5217\u4ec5 method \u7684\u8986\u76d6\u7387。</p><div id="method-coverage-cards" class="growth-grid"></div><div class="notice">\u8fd9\u662f\u6a21\u578b\u6620\u5c04\u7684\u590d\u7528\u8986\u76d6\u7387，\u6ca1\u6709\u72ec\u7acb\u65b9\u6cd5\u5168\u96c6\u4f5c\u5206\u6bcd，\u4e0d\u80fd\u89e3\u91ca\u4e3a\u771f\u5b9e\u79d1\u7814\u65b9\u6cd5\u8986\u76d6\u7387\u6216\u5206\u7c7b\u51c6\u786e\u7387；\u5c1a\u672a\u6392\u9664\u65b9\u6cd5\u9897\u7c92\u5ea6\u8fc7\u7ec6\u7684\u95ee\u9898。</div><div class="table-wrap"><table><thead><tr><th>\u65b0\u589e\u8bba\u6587</th><th>\u672c\u7bc7\u4e0d\u540c M</th><th>\u524d\u5341\u7bc7\u8986\u76d6 M</th><th>\u524d\u5341\u7bc7\u8986\u76d6\u7387</th><th>\u6b64\u524d\u6240\u6709\u8bba\u6587\u8986\u76d6 M</th><th>\u6b64\u524d\u76ee\u5f55\u8986\u76d6\u7387</th></tr></thead><tbody id="method-coverage-table"></tbody></table></div><details><summary>\u8de8\u8bba\u6587\u5171\u4eab\u7684\u5177\u4f53\u65b9\u6cd5（\u542b\u8bba\u6587\u7f16\u53f7）</summary><div id="shared-method-list"></div></details><details><summary>\u8986\u76d6\u7387\u53e3\u5f84\u4e0e\u9650\u5236</summary><pre id="method-coverage-definitions"></pre></details></div>'
COVERAGE_JS = '\nconst cov=DATA.method_coverage,cs=cov.summary,methodOnly=cov.by_kind.find(x=>x.kind===\'method\'),pct=x=>x==null?\'\u65e0\u5206\u6bcd\':(100*x).toFixed(1)+\'%\';\n$(\'method-coverage-cards\').innerHTML=[[\'\u524d\u5341\u7bc7\u76ee\u5f55\u8986\u76d6\u65b0\u5341\u7bc7\',pct(cs.frozen_ten_type_coverage),cs.frozen_ten_covered_method_occurrences+\' / \'+cs.added_paper_method_occurrences+\' \u4e2a\u7bc7\u5185\u65b9\u6cd5\u79cd\u7c7b\'],[\'\u9010\u7bc7\u52a0\u5165\u65f6\u5df2\u6709\u76ee\u5f55\u8986\u76d6\u7387\',pct(cs.prior_type_coverage),cs.prior_covered_method_occurrences+\' / \'+cs.added_paper_method_occurrences+\'；\u542b\u5148\u52a0\u5165\u7684\u65b0\u8bba\u6587\u65b9\u6cd5\'],[\'\u524d\u5341\u7bc7\u76ee\u5f55\u8986\u76d6\u7ec4\u4ef6\u5b9e\u4f8b\',pct(cs.frozen_ten_component_coverage),\'\u6309\u7ec4\u4ef6\u52a0\u6743，\u4e0e\u65b9\u6cd5\u79cd\u7c7b\u53e3\u5f84\u5206\u5f00\'],[\'\u5168\u4e8c\u5341\u7bc7\u5171\u4eab\u65b9\u6cd5\',cs.shared_method_types_all_papers,\'\u540c\u4e00 M \u81f3\u5c11\u88ab\u4e24\u7bc7\u8bba\u6587\u4f7f\u7528；\u542b\u7b56\u7565、\u6307\u6807\'],[\'\u4ec5 method：\u524d\u5341\u7bc7\u8986\u76d6\u7387\',pct(methodOnly.frozen_ten_type_coverage),methodOnly.frozen_ten_covered_occurrences+\' / \'+methodOnly.added_paper_method_occurrences+\'，\u6392\u9664\u7b56\u7565\u4e0e\u6307\u6807\'],[\'\u4ec5 method：\u9010\u7bc7\u5df2\u6709\u76ee\u5f55\u8986\u76d6\u7387\',pct(methodOnly.prior_type_coverage),methodOnly.prior_covered_occurrences+\' / \'+methodOnly.added_paper_method_occurrences+\'，\u6392\u9664\u7b56\u7565\u4e0e\u6307\u6807\']].map(([t,n,note])=>`<div class="growth-card"><h3>${esc(t)}</h3><div class="growth-number">${n}</div><p class="muted small">${esc(note)}</p></div>`).join(\'\');\n$(\'method-coverage-table\').innerHTML=cov.per_paper.filter(x=>!x.seed_frozen).map(x=>`<tr><td>${esc(x.paper)}</td><td>${x.distinct_methods}</td><td>${x.covered_by_frozen_ten_methods}</td><td>${pct(x.frozen_ten_type_coverage)}</td><td>${x.covered_by_prior_methods}</td><td>${pct(x.prior_method_type_coverage)}</td></tr>`).join(\'\');\n$(\'shared-method-list\').innerHTML=cov.method_paper_coverage.filter(x=>x.paper_count>1).sort((a,b)=>b.paper_count-a.paper_count).map(x=>`<p>${esc(x.method_id+\' \'+x.name)} → ${esc(x.papers.join(\'、\'))}</p>`).join(\'\')||\'<p>\u5f53\u524d\u6a21\u578b\u76ee\u5f55\u6ca1\u6709\u5171\u4eab Method。</p>\';\n$(\'method-coverage-definitions\').textContent=JSON.stringify({definitions:cov.definitions,by_kind:cov.by_kind,limits:cov.limits},null,2);\n'
GROWTH_JS = '\nconst growth=DATA.convergence.growth;\n$(\'growth-summary\').textContent=DATA.convergence.summary;\n$(\'growth-cards\').innerHTML=[[\'\u5bb6\u65cf F\',DATA.stats.families,DATA.stats.shared_families+\' \u4e2a\u8986\u76d6\u591a\u7bc7\'],[\'\u5177\u4f53\u65b9\u6cd5 M\',DATA.stats.methods,DATA.stats.shared_methods+\' \u4e2a\u8986\u76d6\u591a\u7bc7\'],[\'\u6700\u540e\u4e09\u7bc7\u65b0\u589e F\',DATA.convergence.last_three_new_families,\'\u6309\u5f53\u524d\u56fa\u5b9a\u987a\u5e8f\u8ba1\u6570\'],[\'\u6700\u540e\u4e09\u7bc7\u65b0\u589e M\',DATA.convergence.last_three_new_methods,\'\u4e0d\u4ee5\u5171\u4eab\u7387\u5224\u65ad\u79d1\u5b66\u6b63\u786e\u6027\']].map(([t,n,note])=>`<div class="growth-card"><h3>${esc(t)}</h3><div class="growth-number">${n}</div><p class="muted small">${esc(note)}</p></div>`).join(\'\');\nfunction growthChart(kind){const w=760,h=315,left=52,right=20,top=30,bottom=52,n=growth.length,plotW=w-left-right,plotH=h-top-bottom,step=plotW/Math.max(n-1,1),max=Math.max(1,...growth.map(g=>kind===\'cumulative\'?g.cumulative_methods:g.new_methods+g.reused_method_types)),cap=Math.max(5,Math.ceil(max/5)*5),x=i=>left+step*i,y=v=>top+plotH*(1-v/cap);let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${kind===\'cumulative\'?\'\u7d2f\u8ba1\u5bb6\u65cf\u4e0e\u65b9\u6cd5\u6570\u91cf\':\'\u6bcf\u7bc7\u65b0\u589e\u4e0e\u590d\u7528\u65b9\u6cd5\'}"><rect width="${w}" height="${h}" fill="white"/>`;\nif(kind===\'cumulative\')svg+=`<rect x="${left-12}" y="${top}" width="${Math.max(20,step*2+24)}" height="${plotH}" fill="#f1f4f8"/><text x="${left+8}" y="${top+18}" font-size="12" fill="#63748a">\u539f\u4e09\u7bc7</text>`;\nfor(let k=0;k<=5;k++){const val=cap*k/5,yy=y(val);svg+=`<line x1="${left}" y1="${yy}" x2="${w-right}" y2="${yy}" stroke="#e0e6ef"/><text x="${left-9}" y="${yy+4}" text-anchor="end" font-size="12" fill="#63748a">${Number(val.toFixed(1))}</text>`;}\nif(kind===\'cumulative\'){for(const [key,color,label] of [[\'cumulative_methods\',\'#315f9c\',\'\u5177\u4f53\u65b9\u6cd5 M\'],[\'cumulative_families\',\'#8b59a6\',\'\u5bb6\u65cf F\']]){svg+=`<polyline fill="none" stroke="${color}" stroke-width="2.5" points="${growth.map((g,i)=>x(i)+\',\'+y(g[key])).join(\' \')}"/>`;for(let i=0;i<n;i++)svg+=`<circle cx="${x(i)}" cy="${y(growth[i][key])}" r="4" fill="${color}"><title>${esc(growth[i].paper+\' · \'+label+\' \'+growth[i][key])}</title></circle>`;}svg+=\'<text x="370" y="20" font-size="13" fill="#315f9c">\u84dd：\u7d2f\u8ba1 M</text><text x="515" y="20" font-size="13" fill="#8b59a6">\u7d2b：\u7d2f\u8ba1 F</text>\';}else{const bw=Math.min(38,plotW/n*.7);for(let i=0;i<n;i++){const g=growth[i],xx=x(i)-bw/2;svg+=`<rect x="${xx}" y="${y(g.reused_method_types)}" width="${bw}" height="${plotH*g.reused_method_types/cap}" fill="#55956e"><title>${esc(g.paper+\' \u590d\u7528 \'+g.reused_method_types)}</title></rect><rect x="${xx}" y="${y(g.reused_method_types+g.new_methods)}" width="${bw}" height="${plotH*g.new_methods/cap}" fill="#ce9248"><title>${esc(g.paper+\' \u65b0\u589e \'+g.new_methods)}</title></rect>`;}svg+=\'<text x="300" y="20" font-size="13" fill="#55956e">\u7eff：\u5df2\u6709 M</text><text x="450" y="20" font-size="13" fill="#a06c29">\u6a59：\u65b0\u589e M</text>\';}\nfor(let i=0;i<n;i++)svg+=`<text x="${x(i)}" y="${h-bottom+22}" text-anchor="middle" font-size="12" fill="#42536a">${esc(growth[i].paper)}</text>`;return svg+\'</svg>\';}\n$(\'cumulative-chart\').innerHTML=growthChart(\'cumulative\');$(\'novelty-chart\').innerHTML=growthChart(\'novelty\');\n$(\'growth-table\').innerHTML=growth.map(g=>{const p=DATA.papers.find(p=>p.alias===g.paper);return `<tr><td><strong>${esc(g.paper)}</strong><br>${esc(g.title)}${g.baseline_frozen?\'<br>\'+badge(\'\u51bb\u7ed3\u57fa\u7ebf\'):\'\'}</td><td>${esc((p.languages||[]).join(\' / \'))}</td><td>${g.new_families}</td><td>${g.new_methods}</td><td>${g.reused_method_types}</td><td>${g.cumulative_families} / ${g.cumulative_methods}</td><td>${(g.reuse_rate*100).toFixed(1)}%</td></tr>`;}).join(\'\');\n$(\'growth-limits\').innerHTML=DATA.convergence.limits.map(x=>\'<li>\'+esc(x)+\'</li>\').join(\'\');$(\'selection-rule\').textContent=JSON.stringify(DATA.selection_rule,null,2);\n$(\'paper-filter\').innerHTML=\'<option value="all">\u5168\u90e8\u8bba\u6587</option>\'+DATA.papers.map(p=>`<option value="${p.alias}">${esc(p.alias+\' · \'+p.title)}</option>`).join(\'\');$(\'paper-filter\').value=\'all\';\nfor(const id of [\'paper-filter\',\'shared-only\'])$(id).onchange=draw;$(\'graph-search\').oninput=draw;$(\'growth-to-graph\').onclick=()=>{$(\'view\').value=\'mapping\';setScope(\'all\');showTab(\'graph\');};\n'
